mapper.select:
SELECT st.id, st.school_id, s.school_name AS school_name, st.class_id, st.grade_id, c.class_name AS class_name, g.grade_name AS grade_name, NULL AS user_id, st.student_code AS student_number, st.student_name AS name, st.gender, st.phone, NULL AS id_card, NULL AS birthday, NULL AS enroll_date, st.bind_code, st.status, '' AS remark, st.create_time FROM student st LEFT JOIN school s ON st.school_id = s.id LEFT JOIN class_info c ON st.class_id = c.id LEFT JOIN grade g ON st.grade_id = g.id WHERE st.deleted = 0
AND st.school_id = #{query.schoolId}
AND st.class_id = #{query.classId}
AND c.grade_id = #{query.gradeId}
AND st.student_code = #{query.studentNumber}
AND st.student_name LIKE CONCAT('%', #{query.name}, '%')
AND st.status = #{query.status}
ORDER BY st.student_code ASC

SELECT id, school_id, class_id, student_code AS student_number, student_name AS name, gender, '' AS remark FROM student WHERE class_id = #{classId} AND deleted = 0
AND status = #{status}
ORDER BY student_code ASC

SELECT * FROM student
WHERE student_code = #{studentNumber}
AND student_name = #{name}
AND deleted = 0

SELECT *
FROM student
WHERE school_id = #{schoolId}
  AND student_code = #{studentNumber}
  AND deleted = 0
LIMIT 1
